<template><section class="discussion-workspace-new" aria-label="Agent discussion workspace">
<header class="workspace-heading"><div><h2>Agent discussion</h2><p>{{ run.status==='running'?'Live source updates · messages appear when recorded':run.status==='queued'?'Queued · no requests have completed yet':['failed','interrupted','cancelled'].includes(run.status)?'Stopped · earlier completed messages remain saved':'Saved discussion' }}<span v-if="run.reassessed_from_run_id"> · Earlier discussion reused</span></p></div><button class="plain-button" @click="openEvidence">Chart & cited evidence ↗</button></header>
<div v-if="run.verdict" class="recorded-takeaway"><strong>Recorded context</strong><span>{{ run.verdict.trade_readiness?.decision==='no_trade'?'No trade now':run.verdict.trade_readiness?.decision||'Readiness not recorded' }} · {{ run.verdict.bias||'Bias not recorded' }} · Original assessment in details</span></div>
<div class="room-bar"><div class="room-tabs" role="tablist" aria-label="Discussion rooms"><button v-for="room in ['specialists','traders']" :key="room" role="tab" :aria-selected="selection.room===room" :aria-controls="'discussion-room-'+room" @click="chooseRoom(room)">{{ room==='specialists'?'Analysts':'Traders' }} <small>{{ discussionData(run,room).people.length }}</small></button></div><div class="exchange-controls"><button class="plain-button follow-button" :aria-pressed="following" @click="following?following=false:followLive()">{{ unread?unread+' new messages · Follow live':following?'Following live':'Follow live' }}</button><select aria-label="Discussion participant" :value="selection.personId" @change="selectPerson($event.target.value)"><option value="" disabled>Choose a participant</option><option v-for="person in data.people" :key="person.id" :value="person.id">{{ person.label }}</option></select><button class="plain-button" :disabled="!exchange?.events.length" @click="replaying?stopReplay():replaySelected()">{{ replaying?'Stop exchange replay':'Replay selected exchange' }}</button></div></div>
<section :id="'discussion-room-'+selection.room" role="tabpanel" :aria-label="selection.room==='specialists'?'Analyst room':'Trader room'"><div class="discussion-columns"><div class="graph-column"><AgentPlayground :generation-active="run.status==='running'" :spotlight-people="exchange?.personIds||[]" :sender-id="exchange?.question?.author||exchange?.reply?.author||exchange?.opening?.author" :receiver-ids="exchange?.question?.recipients||exchange?.reply?.recipients||[]" :people="data.people" :events="data.events" :title="selection.room==='specialists'?'Analyst playground':'Trader playground'" :lens="selection.room" :seed="run.id+'-discussion-'+selection.room" :focus="selection.personId" :active="activeEvent" :selected-event-ids="exchange?.events.map(e=>e.id)||[]" :quiet-header="run.status!=='running'&&run.status!=='queued'" :minimum-height="300" readable-labels selectable-edges hide-open-button :evidence="Boolean(run.observation)" hub-label="Chart evidence" @select="selectPerson" @edge-select="selectEdge"/><p class="graph-hint">Orange question · blue reply · faint recorded connections. Select a participant or a recorded line.</p>
<label class="exchange-select">Selected recorded exchange<select aria-label="Recorded exchange" :value="selection.exchangeId" @change="selectExchange($event.target.value)"><option v-if="!exchange" value="">No recorded exchange for this participant</option><option v-for="item in data.exchanges" :key="item.id" :value="item.id">{{ exchangeLabel(item) }}</option></select></label></div>
<section class="selected-thread" aria-label="Selected conversation"><header><div><p class="eyebrow">{{ replaying?'Replaying saved exchange · no AI requests':'Selected recorded exchange' }}</p><h3>{{ exchange?exchangeLabel(exchange):'No recorded conversation yet' }}</h3><p v-if="selection.personId" class="thread-pair">{{ name(selection.personId) }} · {{ person?.status||'Status not recorded' }}</p></div></header>
<div class="thread-body" v-if="exchange"><div class="thread-column"><ExchangeMessage v-if="exchange.question" :event="exchange.question" :name="name(exchange.question.author)" caption="Recorded question" :text="exchange.question.text"/><ExchangeMessage v-else-if="exchange.opening" :event="exchange.opening" :name="name(exchange.opening.author)" caption="Opening view" :text="exchange.opening.text"/><template v-else-if="exchange.context.length"><h4>Original supplied peer context</h4><ExchangeMessage v-for="(context,index) in exchange.context" :key="index" tone="context" :name="name(context.author)" :caption="context.kind" :text="context.text"/></template><p v-else class="empty-note">No separate question was recorded for this message.</p></div><div class="thread-column"><ExchangeMessage v-if="exchange.reply" tone="reply" :event="exchange.reply" :name="name(exchange.reply.author)" :caption="exchange.kind==='cross_group'?'Cross-group response':'Recorded reply'" :text="exchange.reply.text"/><p v-else class="empty-note">{{ exchange.question?'A matching reply has not been recorded.':'This opening view has no linked reply. Choose a recorded question or response to inspect its exchange.' }}</p></div>
<section v-if="exchange.reply" class="recorded-outcome"><h4>What changed?</h4><p>Recorded stance change: <b>{{ change.changed }}</b> · {{ change.initial }} → {{ change.stance }} · Setup status: {{ change.setup }}</p></section>
<details class="supporting-notes"><summary>Supporting notes · original participant, message and model records</summary><section class="full-outcome"><h4 v-if="outcome">View after exchange · original full text</h4><p v-if="outcome">{{ outcome.text }}</p><h4 v-if="exchange.reply?.message.change_reason">Recorded change reason</h4><p v-if="exchange.reply?.message.change_reason">{{ exchange.reply.message.change_reason }}</p><h4 v-if="exchange.reply?.message.remaining_disagreement">Remaining disagreement</h4><p v-if="exchange.reply?.message.remaining_disagreement">{{ exchange.reply.message.remaining_disagreement }}</p></section><p>Model recorded for this run: {{ run.model||'Not recorded' }}</p><p v-if="selection.room==='traders'">Trader identities share batched requests. Replay highlights saved speech, not independent model processes.</p><details><summary>Participant role/profile</summary><pre>{{ JSON.stringify(person?.role||person?.trader||person,null,2) }}</pre></details><details><summary>Original selected message records</summary><pre>{{ JSON.stringify(exchange.events.map(e=>e.message),null,2) }}</pre></details><p v-if="run.resume_note">{{ run.resume_note }}</p></details></div><p v-else class="empty-note thread-empty">{{ data.people.length?'This participant has no validated saved message yet.':'Participant identities are not available for this room yet.' }}</p>
<footer><button class="text-button" @click="openEvidence">Chart & cited evidence ↗</button><button class="text-button" @click="openTranscript">Full saved transcript ↗</button></footer></section></div></section>
<details v-if="selection.room==='traders'&&completionAction" class="consensus completion-action"><summary>Continue unfinished trader analysis</summary><p>{{ completionAction.reason }}</p><button class="plain-button" :disabled="completionAction.disabled" @click="$emit('resume-traders')">{{ completionAction.label }}</button></details>
<details ref="transcript" class="transcript"><summary>Full saved transcript · {{ selection.room==='specialists'?'Analysts':'Traders' }} · {{ data.events.length }} messages</summary><div class="transcript-body"><ExchangeMessage v-for="event in data.events" :key="event.id" full :event="event" :name="name(event.author)" :caption="event.kind.replaceAll('_',' ')" :tone="event.kind.includes('reply')?'reply':'question'" :text="event.text"/></div></details>
<details class="consensus"><summary>Moderator consensus, unresolved differences & source information</summary><p v-if="run.verdict?.headline">{{ run.verdict.headline }}</p><p v-if="run.verdict?.explanation">{{ run.verdict.explanation }}</p><details v-if="run.verdict?.discussion||run.verdict?.changed_views"><summary>Original moderator discussion & changed-view records</summary><pre>{{ JSON.stringify({discussion:run.verdict.discussion,changed_views:run.verdict.changed_views},null,2) }}</pre></details><p v-if="run.verdict?.bias_reason">{{ run.verdict.bias_reason }}</p><h4 v-if="run.verdict?.agreement?.length">Recorded agreements</h4><ul><li v-for="text in run.verdict?.agreement||[]" :key="text">{{ text }}</li></ul><h4 v-if="run.verdict?.disagreements?.length">Recorded disagreements</h4><ul><li v-for="text in run.verdict?.disagreements||[]" :key="text">{{ text }}</li></ul><p v-if="run.verdict?.simulation_takeaway">{{ run.verdict.simulation_takeaway }}</p><p v-if="run.market_context?.alignment">{{ run.market_context.alignment }}</p><h4 v-if="run.news_sources?.length">Macro source records</h4><p v-for="source in run.news_sources||[]" :key="source.id"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }}</a> · {{ source.published_at }}</p><p v-if="!run.verdict">A final assessment has not been recorded.</p></details>
<dialog ref="evidenceDialog" class="evidence-dialog" aria-labelledby="discussion-evidence-title" @close="closeEvidence"><header><h3 id="discussion-evidence-title">Original chart & cited evidence</h3><button class="plain-button" @click="evidenceDialog?.close()">Close</button></header><ChartSource v-if="evidenceOpen" :run="run" :api="api" v-model:plan-key="planKey"/><p class="empty-note">Screenshot estimates · current market time unverified. Only references passing the existing strict R policy can have trade overlays.</p><section v-if="run.observation"><h4>Recorded chart observations</h4><p>{{ run.observation.summary }}</p><ul><li v-for="id in citedIds" :key="id"><b>{{ id }}</b> · {{ evidenceText(id) }}</li></ul><details><summary>Original chart limitations</summary><ul><li v-for="item in run.observation.limitations||[]" :key="item">{{ item }}</li></ul></details></section></dialog>
</section></template>
<script setup>
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import AgentPlayground from './AgentPlayground.vue'
import ExchangeMessage from './ExchangeMessage.vue'
import ChartSource from './ChartSource.vue'
import {discussionRoom,discussionData,resolveDiscussionSelection,exchangeForEdge,recordedExchangeOutcome,recordedExchangeChange,replayExchange,traderCompletionAction} from '../utils/discussionWorkspace.mjs'
const props=defineProps({run:{type:Object,required:true},api:{type:String,required:true},initialRoom:String,resuming:Boolean})
const emit=defineEmits(['room','resume-traders'])
const planKey=defineModel('planKey',{default:''})
const selection=ref({room:discussionRoom(props.initialRoom),personId:'',exchangeId:''}),data=computed(()=>discussionData(props.run,selection.value.room)),exchange=computed(()=>data.value.exchanges.find(e=>e.id===selection.value.exchangeId)),person=computed(()=>data.value.people.find(p=>p.id===selection.value.personId)),outcome=computed(()=>recordedExchangeOutcome(exchange.value)),change=computed(()=>recordedExchangeChange(exchange.value))
const completionAction=computed(()=>traderCompletionAction(props.run,props.resuming))
const following=ref(['running','queued'].includes(props.run.status)),unread=ref(0)
const activeEvent=ref(null),replaying=ref(false);let timers=[],liveTimer;let seenEvents=new Set(data.value.events.map(e=>e.id))
function stopReplay(){clearTimeout(liveTimer);timers.forEach(clearTimeout);timers=[];replaying.value=false;activeEvent.value=null}
function replaySelected(){following.value=false;stopReplay();const events=replayExchange(exchange.value);if(!events.length)return;replaying.value=true;events.forEach((event,index)=>timers.push(setTimeout(()=>{activeEvent.value=event},index*1500)));timers.push(setTimeout(stopReplay,events.length*1500))}
function chooseRoom(room,notify=true){following.value=['running','queued'].includes(props.run.status);unread.value=0;stopReplay();seenEvents=new Set(discussionData(props.run,room).events.map(e=>e.id));selection.value=resolveDiscussionSelection(discussionData(props.run,room),{room,personId:'',exchangeId:''});if(transcript.value)transcript.value.open=false;if(notify)emit('room',room)}
function selectPerson(id){following.value=false;stopReplay();selection.value=resolveDiscussionSelection(data.value,{...selection.value,personId:id,exchangeId:''})}
function selectExchange(id,manual=true){if(manual)following.value=false;stopReplay();const item=data.value.exchanges.find(e=>e.id===id);if(!item)return;selection.value={room:data.value.room,personId:item.question?.author||item.reply?.author||item.opening?.author||'',exchangeId:item.id}}
function selectEdge(edge){const item=exchangeForEdge(data.value,edge);if(item)selectExchange(item.id)}
watch(()=>props.run.id,()=>{seenEvents=new Set();chooseRoom(discussionRoom(props.initialRoom),false)})
watch(()=>props.initialRoom,room=>{if(discussionRoom(room)!==selection.value.room)chooseRoom(discussionRoom(room),false)})
watch(data,next=>{const resolved=resolveDiscussionSelection(next,selection.value);if(resolved.room!==selection.value.room||resolved.personId!==selection.value.personId||resolved.exchangeId!==selection.value.exchangeId)selection.value=resolved;const incoming=next.events.filter(event=>!seenEvents.has(event.id));next.events.forEach(e=>seenEvents.add(e.id));if(!incoming.length)return;if(!following.value||replaying.value){unread.value+=incoming.length;return}const newest=incoming.at(-1),item=next.exchanges.find(e=>e.events.some(event=>event.id===newest.id));if(item)selectExchange(item.id,false);if(!newest.reused){clearTimeout(liveTimer);activeEvent.value=newest;liveTimer=setTimeout(()=>{activeEvent.value=null},1400)}},{immediate:true})
function followLive(){following.value=true;unread.value=0;const latest=data.value.events.at(-1),item=data.value.exchanges.find(e=>e.events.some(event=>event.id===latest?.id));if(item)selectExchange(item.id,false)}

const name=id=>data.value.people.find(p=>p.id===id)?.label||id
const exchangeLabel=item=>item.kind==='paired'?`${name(item.question.author)} → ${item.question.recipients.map(name).join(', ')}`:item.kind==='cross_group'?`${name(item.reply.author)} · cross-group response`:`${name(item.opening?.author||item.reply?.author)} · ${item.kind==='opening'?'opening view':'recorded reply'}`
const transcript=ref(null),evidenceDialog=ref(null),evidenceOpen=ref(false);let returnFocus=null
async function openEvidence(){returnFocus=document.activeElement;evidenceOpen.value=true;await nextTick();evidenceDialog.value?.showModal()}
function closeEvidence(){evidenceOpen.value=false;returnFocus?.focus?.()}
async function openTranscript(){if(transcript.value)transcript.value.open=true;await nextTick();transcript.value?.scrollIntoView({block:'start'})}
const citedIds=computed(()=>[...new Set((exchange.value?.events||[]).flatMap(e=>e.message.evidence_ids||[]))])
const evidenceText=id=>id==='OBS:chart'?props.run.observation?.summary:props.run.observation?.levels?.find(level=>level.id===id)?.evidence||props.run.news_sources?.find(source=>source.id===id)?.title||'The identifier is preserved; a separate source detail is not recorded here.'
onBeforeUnmount(stopReplay)
</script>
<style scoped>
