t-weight:550;margin:0}.evidence-dialog p,.evidence-dialog li{font-size:12px;line-height:1.7}.evidence-dialog ul{padding-left:18px}.evidence-dialog h4{font-size:13px}.transcript-body{scrollbar-width:thin;scrollbar-color:#cedae7 transparent}@media(max-width:700px){.room-bar{align-items:start;flex-direction:column;gap:10px}.exchange-controls{width:100%;flex-wrap:wrap}.exchange-controls select{flex:1;max-width:none}.workspace-heading h2{font-size:22px}.workspace-heading{gap:10px}.thread-body{grid-template-columns:1fr;padding:14px}.recorded-takeaway{flex-direction:column;gap:3px}.selected-thread h3{font-size:15px}.exchange-select{align-items:start;flex-direction:column;gap:6px}.exchange-select select{width:100%}.selected-thread footer{flex-wrap:wrap;gap:12px}}

.consensus pre{font:11px/1.7 monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.full-outcome p{white-space:pre-wrap;color:#637b94;font-size:12px;line-height:1.8}.full-outcome h4{font-size:12px;font-weight:550;margin:14px 0 5px}.outcome-excerpt{font-size:11px;color:#8695a7}

.discussion-columns{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:16px;align-items:start}.graph-column{min-width:0}.discussion-columns .thread-body{grid-template-columns:1fr;gap:16px}.selected-thread{box-shadow:0 4px 24px #35506608}.selected-thread>header{background:#fdfdfd}.recorded-takeaway{background:#fbfcfd;border-left-color:#aebecb;border-radius:4px;padding:10px 13px}.recorded-takeaway strong{color:#60758c}.follow-button[aria-pressed=true]{border-color:#d1dfea;background:#f4f8fc;color:#4c7396}.thread-column :deep(.message-copy){font-size:12px;line-height:1.7}.graph-column :deep(.playground){margin-bottom:8px}@media(max-width:700px){.discussion-columns{grid-template-columns:1fr}.exchange-controls .follow-button{flex-basis:100%;text-align:left}}

.discussion-workspace-new{margin:10px 0}.workspace-heading h2{font-size:19px;margin-bottom:3px}.workspace-heading p{font-size:10px}.recorded-takeaway{margin:9px 0;padding:6px 10px;font-size:10px}.room-bar{margin:10px 0}.room-tabs button{padding:6px 10px}.selected-thread>header{padding:10px 13px}.selected-thread h3{font-size:14px}.thread-body{padding:13px;gap:12px}.thread-pair{font-size:10px}.selected-thread footer{padding:9px 13px}.recorded-outcome{font-size:10px;line-height:1.5}.recorded-outcome h4{font-size:11px;margin-bottom:3px}.graph-hint{margin-bottom:9px}.exchange-select{margin:8px 0}.exchange-controls select{max-width:185px}.exchange-controls{gap:6px}.supporting-notes{padding-top:9px}
</style>
